-- SELECT only. 20261128100000_mcp_claude_write 적용 전(시험 적용 전후 비교에도 씀). 카탈로그·migration 기록·허용 행 개수만 읽는다(행 값 없음).
-- 기대: 예/아니오 항목은 모두 예, mcp_write rows 0. 해시는 기록만 하고 사후 확인에서 같은 값이어야 한다(읽기 함수·문지기·쓰는 표의 권한·정책·트리거가 그대로라는 뜻).
-- expect: new migration absent = 예
-- expect: read areas and photo content applied = 예
-- expect: prerequisite columns present = 예
-- expect: gates and helpers present = 예
-- expect: write objects absent = 예
-- expect: feature check with photo_content without mcp_write = 예
-- expect: single calls workspace = 예
-- expect: mcp_write rows = 0
-- expect: existing boundary hash = 기록
select 'new migration absent' as item,case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261128100000') then '예' else '아니오' end as value
union all select 'read areas and photo content applied',case when (select count(*) from supabase_migrations.schema_migrations where (version='20261127120000' and name='mcp_claude_read_areas') or (version='20261126190000' and name='photo_content_feature'))=2 then '예' else '아니오' end
union all select 'prerequisite columns present',case when (select count(*) from (values ('app_notes','kind'),('app_notes','title'),('app_notes','raw_text'),('app_notes','doc'),('app_notes','metadata'),('app_notes','journal_day'),('app_notes','ai_export_allowed'),('app_notes','deleted_at'),('app_notes','occurred_at'),('app_notes','updated_at'),('app_notes','workspace_id'),('app_note_folders','workspace_id'),('app_note_folders','name'),('app_suborganizations','workspace_id'),('app_suborganizations','name'),('app_suborganizations','deleted_at'),('app_suborganization_updates','organization_id'),('app_suborganization_updates','raw_text'),('app_suborganization_updates','doc'),('app_suborganization_updates','one_line'),('app_suborganization_updates','occurred_at'),('app_suborganization_updates','created_by'),('app_suborganization_updates','created_at'),('app_suborganization_updates','updated_at'),('app_spaces','workspace_id'),('app_spaces','name'),('app_spaces','deleted_at'),('app_business_records','workspace_id'),('app_business_records','space_id'),('app_business_records','day'),('app_business_records','body'),('app_business_records','source_kind'),('app_business_records','updated_at')) v(t,c) join pg_attribute a on a.attrelid=to_regclass('public.'||v.t) and a.attname=v.c and not a.attisdropped)=33 then '예' else '아니오' end
union all select 'gates and helpers present',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_mcp_gate(text)') and prosecdef) and exists(select 1 from pg_proc where oid=to_regprocedure('private.app_mcp_locked_areas()') and prosecdef) and exists(select 1 from pg_proc where oid=to_regprocedure('private.app_workspace_has_feature(uuid,text)') and prosecdef) and to_regprocedure('private.app_mcp_note_locks()') is not null and to_regprocedure('private.app_mcp_arg(text,integer)') is not null and to_regprocedure('private.app_mcp_page(text,integer)') is not null and to_regprocedure('private.app_mcp_uuid(text)') is not null and to_regprocedure('public.app_trash_restore(text,uuid)') is not null then '예' else '아니오' end
union all select 'write objects absent',case when to_regclass('public.app_mcp_write_log') is null and to_regclass('public.app_mcp_write_before') is null and not exists(select 1 from pg_attribute a where a.attrelid=to_regclass('public.app_mcp_settings') and a.attname='write_enabled' and not a.attisdropped) and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname in ('app_mcp_write','app_mcp_write_tools','app_mcp_write_undo','app_mcp_write_check','app_mcp_write_gate','app_mcp_write_note','app_mcp_w_diary_locked','app_mcp_w_text','app_mcp_w_version','app_mcp_w_day','app_mcp_w_note_blocked')) then '예' else '아니오' end
union all select 'feature check with photo_content without mcp_write',case when (select count(*) from pg_constraint where conrelid=to_regclass('public.app_operator_features') and conname='app_operator_features_feature_check' and pg_get_constraintdef(oid) ~ '''photo_content''' and pg_get_constraintdef(oid) !~ '''mcp_write''')=1 then '예' else '아니오' end
union all select 'single calls workspace',case when (select count(*) from public.app_operator_features where feature='calls')=1 then '예' else '아니오' end
union all select 'mcp_write rows',(select count(*) from public.app_operator_features where feature::text='mcp_write')::text
union all select 'existing boundary hash',md5(coalesce((select string_agg(p.oid::regprocedure::text||md5(pg_get_functiondef(p.oid))||coalesce(p.proacl::text,''),',' order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname in('public','private') and p.proname like 'app\_mcp\_%' and p.proname not in ('app_mcp_write','app_mcp_write_tools','app_mcp_write_undo','app_mcp_write_check','app_mcp_write_gate','app_mcp_write_note','app_mcp_w_diary_locked','app_mcp_w_text','app_mcp_w_version','app_mcp_w_day','app_mcp_w_note_blocked')) or p.oid in (to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('private.app_is_workspace_owner(uuid)'),to_regprocedure('public.app_trash_restore(text,uuid)'))),'')||coalesce((select string_agg(c.relname::text||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in (to_regclass('public.app_notes'),to_regclass('public.app_note_folders'),to_regclass('public.app_suborganizations'),to_regclass('public.app_suborganization_updates'),to_regclass('public.app_spaces'),to_regclass('public.app_business_records'),to_regclass('public.app_operator_features'),to_regclass('public.app_mcp_read_log'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(p.polrelid::regclass::text||p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polrelid::regclass::text,p.polname) from pg_policy p where p.polrelid in (to_regclass('public.app_notes'),to_regclass('public.app_note_folders'),to_regclass('public.app_suborganizations'),to_regclass('public.app_suborganization_updates'),to_regclass('public.app_spaces'),to_regclass('public.app_business_records'),to_regclass('public.app_operator_features'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_read_log'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(t.tgrelid::regclass::text||t.tgname::text||t.tgenabled::text,',' order by t.tgrelid::regclass::text,t.tgname) from pg_trigger t where not t.tgisinternal and t.tgrelid in (to_regclass('public.app_notes'),to_regclass('public.app_suborganization_updates'),to_regclass('public.app_business_records'))),''));
